{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/meetings"),
    Content = new StringContent("{\"title\":\"Jon's Meeting\",\"location\":\"Office 123\",\"overview\":\"Overview of meeting\",\"is_private\":true,\"conclusion\":\"My conclusion\",\"is_draft\":false,\"time_zone\":\"US/Pacific\",\"remote_meeting_url\":\"https://zoom.us/j/123456789\",\"start_time\":\"10:00 AM\",\"finish_time\":\"11:00 AM\",\"meeting_template_id\":\"82593\",\"custom_textfield_1\":\"My custom text field\",\"custom_textarea_1\":\"My custom text area\",\"position\":6,\"attendees\":[1,2],\"attendee_minutes_approvers\":[1],\"create_uncategorized_items_category\":false,\"meeting_date\":\"2025-07-22\",\"starts_at\":\"2025-07-22T14:00:00Z\",\"ends_at\":\"2025-07-22T15:00:00Z\",\"view\":\"mobile\",\"attachment_ids\":[\"1\",\"2\"],\"drawing_revision_ids\":[\"3\",\"4\"],\"file_version_ids\":[\"5\",\"6\"],\"form_ids\":[\"7\",\"8\"],\"image_ids\":[\"9\",\"10\"],\"upload_ids\":[\"01J15GF28TDQ2X20RNRJ5DDX27\",\"01J15GFDKQ4TDRBQPZ2M6E9H44\"],\"prostore_file_ids\":[1,2],\"document_management_document_revision_ids\":[\"13\",\"14\"]}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

